@props(['paginator'])
@if($paginator->total())<div class="pagination"><span>{{ $paginator->firstItem() }}–{{ $paginator->lastItem() }} de {{ $paginator->total() }} registros</span><nav aria-label="Paginação">@if($paginator->onFirstPage())<span class="page-disabled">Anterior</span>@else<a href="{{ $paginator->previousPageUrl() }}" rel="prev">Anterior</a>@endif<span>{{ $paginator->currentPage() }} / {{ $paginator->lastPage() }}</span>@if($paginator->hasMorePages())<a href="{{ $paginator->nextPageUrl() }}" rel="next">Próxima</a>@else<span class="page-disabled">Próxima</span>@endif</nav></div>@endif
